How do these look to your eyes?

``` js
var assert = require('assert');
function it() {
    return assert.throws(function () {
        return;
    }, function (err) {
        return err.name === 'Error';
    });
}
it();
```

``` js
var fluent = require('./fluent');
function doThat() {
    return fluent()
    .sort(function (a, b) {
        return a - b;
    })    
    .limit()
    .exec();
}
doThat();
```

Neither of above generates any error. Both look fairly common to me.

Here is another example:

``` js
Promise.all([
    promise1,
    promise2
]).then(function () {
    return promise3();
}).then(function () {
    // do something
}, function (e) {
    console.error(e);
});
```

